our last hour.","moment":"evening","moment_v2":"evening","reads":["your-evening-routine"]},"wind_down":{"title_en":"10 minutes to wind down: box breathing or NSDR","how_en":"10 minutes to wind down: box breathing or an NSDR.","moment":"evening","moment_v2":"evening","reads":["nsdr-explained","your-evening-routine"]},"breath_2":{"title_en":"A second moment to breathe","how_en":"A second moment to breathe, in the afternoon.","moment":"day","moment_v2":"afternoon","reads":["breathe-the-time-you-give-yourself"]},"reach_out":{"title_en":"Reach out to someone you care about","how_en":"A message or a call to someone you care about.","moment":"day","moment_v2":"afternoon","reads":["connection-is-health"]},"writing":{"title_en":"5 minutes of writing: three good things, and what''s on your mind","how_en":"5 minutes of writing: three good things, and what''s on your mind.","moment":"evening","moment_v2":"evening","reads":["the-habit-of-writing","three-good-things"]},"flow_10":{"title_en":"10-minute morning flow","how_en":"Ten minutes: your morning flow, longer.","moment":"morning","moment_v2":"morning","reads":["the-power-of-walking"]},"move_2h":{"title_en":"Move 10 minutes every 2 hours","how_en":"Every 2 hours, stand up and move for 10 minutes.","moment":"day","moment_v2":"afternoon","reads":["the-power-of-walking","sitting-less"]}}'::jsonb; v_map jsonb; n int; hb_before int; v_app uuid; v_hidden int; v_chk int;
begin
select count(*) into hb_before from public.habit_bank;
-- 1 habit_bank: one active, published row per v2 habit (daylight reuses the existing row)
update public.habit_bank set title=h.title, description=h.descr, how_md=h.how, resources=h.res, member_can_add=true, default_slot=h.slot, updated_at=now()
  from jsonb_to_record('{"key":"daylight","title":"Daylight first thing: head out of the window, and breathe","pillar":"mind","kind":null,"slot":"morning","dur":null,"descr":"Right when you wake up: daylight and fresh air, before your phone.","how":"1. Right when you wake up, before your phone\n2. Then 5 minutes outside, or at an open window\n3. No sunglasses; never look straight at the sun","res":[{"kind":"article","slug":"light-sets-your-body-clock","title":"Light sets your body clock"},{"kind":"benefits","items":["More awake in the morning","Easier to fall asleep at night","A steadier mood"]},{"kind":"moves","items":[{"label":"Energy","dir":"up"},{"label":"Mood","dir":"up"},{"label":"Sleep","dir":"up"}]}],"sort":207}'::jsonb) as h(title text, descr text, how text, res jsonb, slot text)
 where id='afa499c9-5033-43d3-bf0c-81f2b8e70819';
insert into public.habit_bank (pillar,title,description,how_md,default_slot,duration_min,card_kind,frequency_rule,resources,member_can_add,active,sort_order,published_at)
select h.pillar,h.title,h.descr,h.how,h.slot,h.dur,h.kind,'RRULE:FREQ=DAILY',h.res,true,true,h.sort,now()
  from jsonb_to_recordset('[{"key":"log_meal","title":"Log a meal","pillar":"nutrition","kind":"nutrition","slot":"midday","dur":null,"descr":"Snap your plate before the first bite. Drinks and snacks too.","how":"1. Open Log a meal, point, shoot\n2. Before the first bite, not after\n3. Drinks and snacks count","res":[{"kind":"article","slug":"what-your-meal-photos-tell-us","title":"What your meal photos tell us"},{"kind":"benefits","items":["You see your real pattern, without counting","Your nutritionist sees what you eat","You notice what keeps you full"]},{"kind":"moves","items":[{"label":"Awareness","dir":"up"},{"label":"Cravings","dir":"down"}]}],"sort":200},{"key":"checkin","title":"Do your functional check-in","pillar":"mind","kind":"routine","slot":"evening","dur":null,"descr":"One minute in the evening: how the day landed.","how":"1. Five sliders: energy, sleep, mood, calmness, digestion\n2. Around the same time each evening\n3. Honest beats perfect","res":[{"kind":"article","slug":"your-functional-check-in-explained","title":"Your functional check-in, explained"},{"kind":"benefits","items":["You start to see your own patterns","Your curves appear in Trends","It shows what your habits change"]},{"kind":"moves","items":[{"label":"Awareness","dir":"up"},{"label":"Mood","dir":"up"}]}],"sort":201},{"key":"mindful","title":"Mindful eating: no phone, chew, breathe, a glass of water","pillar":"nutrition","kind":"nutrition","slot":"midday","dur":null,"descr":"No phone, chew a lot, breathe, a glass of water.","how":"1. Phone away, screen off\n2. Chew each bite well; put the fork down between bites\n3. Three breaths before you start, a glass of water with the meal","res":[{"kind":"article","slug":"mindful-eating","title":"Mindful eating"},{"kind":"benefits","items":["Lighter digestion, less bloating","Full sooner, fewer cravings later","Calmer meals"]},{"kind":"moves","items":[{"label":"Digestion","dir":"up"},{"label":"Cravings","dir":"down"},{"label":"Stress","dir":"down"}]}],"sort":202},{"key":"walk_5","title":"A 5-minute walk after eating","pillar":"exercise","kind":"movement","slot":"midday","dur":5,"descr":"Five minutes on your feet after eating.","how":"1. Right after the meal, or within half an hour\n2. Outside if you can; the corridor works too\n3. Easy pace, no sweat","res":[{"kind":"article","slug":"the-5-minute-walk-after-eating","title":"The 5-minute walk after eating"},{"kind":"benefits","items":["Steadier energy after meals","Easier digestion","Less of the afternoon dip"]},{"kind":"moves","items":[{"label":"Energy","dir":"up"},{"label":"Digestion","dir":"up"},{"label":"Cravings","dir":"down"}]}],"sort":203},{"key":"move_3","title":"3 minutes of movement","pillar":"exercise","kind":"movement","slot":"morning","dur":3,"descr":"Three minutes to wake the body.","how":"1. Neck, shoulder and hip circles\n2. 10 slow squats\n3. Reach up, fold down, breathe","res":[{"kind":"article","slug":"little-and-often","title":"Little and often"},{"kind":"benefits","items":["Less stiffness in the morning","More awake, sooner","A first win in your day"]},{"kind":"moves","items":[{"label":"Energy","dir":"up"},{"label":"Mood","dir":"up"}]}],"sort":204},{"key":"snack_opt","title":"Optional: an exercise snack","pillar":"exercise","kind":"movement","slot":"midday","dur":null,"descr":"One short burst of movement, if you feel like it.","how":"1. 10 squats, or a minute up the stairs\n2. Or 10 push-ups against a wall\n3. Any time you''ve been sitting a while","res":[{"kind":"article","slug":"exercise-snacks-foundation","title":"Exercise snacks: small signals that add up"},{"kind":"benefits","items":["Clarity of mind","Stable blood sugar","More energy","A stronger body overall"]},{"kind":"moves","items":[{"label":"Focus","dir":"up"},{"label":"Energy","dir":"up"},{"label":"Mood","dir":"up"}]}],"sort":205},{"key":"stretch","title":"2 minutes of gentle stretching before bed","pillar":"recovery","kind":"movement","slot":"evening","dur":2,"descr":"Two minutes of gentle stretching before bed.","how":"1. Slow, never into pain\n2. Hamstrings, hips, an open chest\n3. A long breath out with each stretch","res":[{"kind":"article","slug":"little-and-often","title":"Little and often"},{"kind":"benefits","items":["Easier to fall asleep","Looser back and hips","A clear end to the day"]},{"kind":"moves","items":[{"label":"Sleep","dir":"up"},{"label":"Stress","dir":"down"}]}],"sort":206},{"key":"caffeine","title":"No caffeine after 16:00","pillar":"sleep","kind":"routine","slot":"midday","dur":null,"descr":"Your last coffee, tea or energy drink before 16:00.","how":"1. Coffee, black and green tea, cola and energy drinks all count\n2. After 16:00: decaf, herbal tea or water\n3. If 16:00 is hard, move it 30 minutes earlier each day","res":[{"kind":"article","slug":"caffeine-and-your-sleep","title":"Caffeine and your sleep"},{"kind":"benefits","items":["Falling asleep faster","Deeper sleep","Needing less caffeine the next morning"]},{"kind":"moves","items":[{"label":"Sleep","dir":"up"},{"label":"Stress","dir":"down"}]}],"sort":208},{"key":"rule_321","title":"The 3-2-1 rule: 3 h no food, 2 h no intense exercise, 1 h no screens","pillar":"sleep","kind":"routine","slot":"evening","dur":null,"descr":"Before bed: 3 hours no food, 2 hours no intense exercise, 1 hour no screens.","how":"1. 3 hours before bed: your last food of the day\n2. 2 hours before: no hard exercise. Stretching, light movement and a walk are fine\n3. 1 hour before: no scrolling. Answering a message is fine; it''s the stimulating stuff you leave","res":[{"kind":"article","slug":"the-3-2-1-rule","title":"The 3-2-1 rule"},{"kind":"article","slug":"your-evening-routine","title":"Your evening routine"},{"kind":"benefits","items":["Falling asleep faster","Waking less in the night","Calmer evenings"]},{"kind":"moves","items":[{"label":"Sleep","dir":"up"},{"label":"Energy","dir":"up"},{"label":"Stress","dir":"down"}]}],"sort":209},{"key":"mini_breath","title":"Optional: a mini breath before sleep","pillar":"mind","kind":"breath","slot":"evening","dur":null,"descr":"A few slow breaths in bed: in through the nose, a long breath out.","how":"1. Lying down, lights off\n2. In through the nose for 4\n3. Out slowly for 6 to 8, five times","res":[{"kind":"article","slug":"breathe-the-time-you-give-yourself","title":"Breathe: the time you give yourself"},{"kind":"benefits","items":["Calmer before sleep","Easier to drop off"]},{"kind":"moves","items":[{"label":"Stress","dir":"down"},{"label":"Sleep","dir":"up"}]}],"sort":210},{"key":"breathing","title":"5 minutes of breathing, once a day","pillar":"mind","kind":"breath","slot":"midday","dur":5,"descr":"5 minutes for yourself, once a day: deep breaths, a slow exhale, a hold.","how":"1. Sit or lie down; never in water or while driving\n2. 30 deep breaths, then breathe out slowly\n3. Hold as long as is comfortable; 2 rounds to start","res":[{"kind":"video","url":"https://www.youtube.com/watch?v=nzCaZQqAs9I","title":"Guided breathing, with Wim Hof","source":"youtube"},{"kind":"article","slug":"breathe-the-time-you-give-yourself","title":"Breathe: the time you give yourself"},{"kind":"benefits","items":["A calmer, clearer head","Energy without coffee","A moment that is yours"]},{"kind":"moves","items":[{"label":"Stress","dir":"down"},{"label":"Focus","dir":"up"},{"label":"Energy","dir":"up"}]}],"sort":211},{"key":"three_good","title":"Write down three good things about your day","pillar":"emotion","kind":"mind","slot":"evening","dur":null,"descr":"Write down three good things about your day.","how":"1. In the evening, in your phone or a journal\n2. Small things count\n3. One line on why it was good","res":[{"kind":"article","slug":"three-good-things","title":"Three good things"},{"kind":"benefits","items":["Falling asleep on a good thought","Over weeks, a more positive outlook","Noticing what helps you"]},{"kind":"moves","items":[{"label":"Mood","dir":"up"},{"label":"Stress","dir":"down"},{"label":"Sleep","dir":"up"}]}],"sort":212},{"key":"flow_5","title":"5-minute morning flow","pillar":"exercise","kind":"movement","slot":"morning","dur":5,"descr":"Five minutes inspired by qi gong: breathe with the arms, twist, shake it out.","how":"1. Slow breathing with the arms\n2. Gentle twists, left and right\n3. Shake it out","res":[{"kind":"article","slug":"your-day-on-one-page","title":"Your day, on one page"},{"kind":"benefits","items":["A loose, awake body","A better mood in the morning","Your first win, every day"]},{"kind":"moves","items":[{"label":"Energy","dir":"up"},{"label":"Mood","dir":"up"},{"label":"Focus","dir":"up"}]}],"sort":213},{"key":"snack_daily","title":"One exercise snack a day","pillar":"exercise","kind":"movement","slot":"midday","dur":null,"descr":"One exercise snack every day, no longer optional.","how":"1. 10 squats, a minute of stairs, or 10 wall push-ups\n2. Once a day, whenever suits you\n3. Easier is always fine","res":[{"kind":"article","slug":"exercise-snacks-foundation","title":"Exercise snacks: small signals that add up"},{"kind":"benefits","items":["Clarity of mind","Stable blood sugar","More energy","A stronger body overall"]},{"kind":"moves","items":[{"label":"Focus","dir":"up"},{"label":"Energy","dir":"up"},{"label":"Mood","dir":"up"}]}],"sort":214},{"key":"protein","title":"Protein at every meal","pillar":"nutrition","kind":"nutrition","slot":"midday","dur":null,"descr":"A palm of protein at every meal.","how":"1. Eggs, yogurt, fish, chicken, tofu, beans or lentils\n2. About the size of your palm\n3. Start with breakfast","res":[{"kind":"article","slug":"protein-at-every-meal-and-why-it-matters","title":"Protein at every meal, and why it matters"},{"kind":"benefits","items":["Fuller for longer","Fewer cravings","Keeping your muscle as you age"]},{"kind":"moves","items":[{"label":"Cravings","dir":"down"},{"label":"Energy","dir":"up"}]}],"sort":215},{"key":"carbs","title":"Complex carbs over refined","pillar":"nutrition","kind":"nutrition","slot":"midday","dur":null,"descr":"Complex carbs rather than refined.","how":"1. Oats, wholegrain bread, beans, quinoa, brown rice\n2. White bread and pasta → wholegrain\n3. Whole fruit rather than juice","res":[{"kind":"article","slug":"complex-or-refined-carbs-why-it-matters","title":"Complex or refined carbs: why it matters"},{"kind":"benefits","items":["Steadier energy","No three o''clock dip","Better digestion, with the fibre"]},{"kind":"moves","items":[{"label":"Energy","dir":"up"},{"label":"Focus","dir":"up"},{"label":"Cravings","dir":"down"}]}],"sort":216},{"key":"walk_meal","title":"A short walk after every meal","pillar":"exercise","kind":"movement","slot":"midday","dur":null,"descr":"A short walk after every meal.","how":"1. 5 to 10 minutes\n2. Right after eating, or within half an hour\n3. Even around the house","res":[{"kind":"article","slug":"the-walk-after-every-meal","title":"The walk after every meal"},{"kind":"benefits","items":["Steadier energy all day","Easier digestion","More steps without trying"]},{"kind":"moves","items":[{"label":"Energy","dir":"up"},{"label":"Digestion","dir":"up"}]}],"sort":217},{"key":"moments","title":"2 to 3 movement moments a day","pillar":"exercise","kind":"movement","slot":"midday","dur":null,"descr":"2 to 3 movement moments a day. It can be as light as a walk.","how":"1. Choose a movement: it can be as light as a walk\n2. Or a few easy moves: squats, calf raises, a chest opener\n3. Push-ups too, if you''re comfortable","res":[{"kind":"article","slug":"muscle-a-long-term-investment","title":"Muscle, a long-term investment"},{"kind":"article","slug":"the-benefits-of-exercise-snacks","title":"The benefits of exercise snacks"},{"kind":"benefits","items":["Clarity of mind","Stable blood sugar","More energy","A stronger body overall"]},{"kind":"moves","items":[{"label":"Focus","dir":"up"},{"label":"Energy","dir":"up"},{"label":"Mood","dir":"up"}]}],"sort":218},{"key":"book","title":"A book instead of a screen","pillar":"sleep","kind":"routine","slot":"evening","dur":null,"descr":"A book instead of a screen in your last hour.","how":"1. Choose tonight''s book now\n2. Paper, or an e-reader without the lights up\n3. Even 10 pages","res":[{"kind":"article","slug":"your-evening-routine","title":"Your evening routine"},{"kind":"benefits","items":["Sleepier at the right time","Less noise in your head","Time for yourself"]},{"kind":"moves","items":[{"label":"Sleep","dir":"up"},{"label":"Stress","dir":"down"}]}],"sort":219},{"key":"wind_down","title":"10 minutes to wind down: box breathing or NSDR","pillar":"sleep","kind":"routine","slot":"evening","dur":10,"descr":"10 minutes to wind down: box breathing or an NSDR.","how":"1. Box breathing: in 4, hold 4, out 4, hold 4\n2. Or a guided NSDR, lying down\n3. Lights low","res":[{"kind":"video","url":"https://www.youtube.com/watch?v=KHIbgSN2qAU","title":"10-minute NSDR","source":"youtube"},{"kind":"article","slug":"nsdr-explained","title":"NSDR, explained"},{"kind":"article","slug":"your-evening-routine","title":"Your evening routine"},{"kind":"benefits","items":["Falling asleep faster","A calmer mind","Better recovery"]},{"kind":"moves","items":[{"label":"Sleep","dir":"up"},{"label":"Stress","dir":"down"}]}],"sort":220},{"key":"breath_2","title":"A second moment to breathe","pillar":"mind","kind":"breath","slot":"midday","dur":null,"descr":"A second moment to breathe, in the afternoon.","how":"1. Same as your morning round, or 5 slow breaths\n2. When the afternoon gets heavy\n3. Away from the screen","res":[{"kind":"video","url":"https://www.youtube.com/watch?v=nzCaZQqAs9I","title":"Guided breathing, with Wim Hof","source":"youtube"},{"kind":"article","slug":"breathe-the-time-you-give-yourself","title":"Breathe: the time you give yourself"},{"kind":"benefits","items":["A reset in the middle of the day","Less tension by the evening"]},{"kind":"moves","items":[{"label":"Stress","dir":"down"},{"label":"Focus","dir":"up"}]}],"sort":221},{"key":"reach_out","title":"Reach out to someone you care about","pillar":"emotion","kind":"mind","slot":"midday","dur":null,"descr":"A message or a call to someone you care about.","how":"1. Think of one person\n2. A message, a voice note or a call\n3. No reason needed","res":[{"kind":"article","slug":"connection-is-health","title":"Connection is health"},{"kind":"benefits","items":["Feeling more connected","A lift in mood","Stronger relationships over time"]},{"kind":"moves","items":[{"label":"Mood","dir":"up"},{"label":"Stress","dir":"down"}]}],"sort":222},{"key":"writing","title":"5 minutes of writing: three good things, and what''s on your mind","pillar":"emotion","kind":"mind","slot":"evening","dur":5,"descr":"5 minutes of writing: three good things, and what''s on your mind.","how":"1. Three good things first\n2. Then whatever is on your mind\n3. No rules, no rereading","res":[{"kind":"article","slug":"the-habit-of-writing","title":"The habit of writing"},{"kind":"article","slug":"three-good-things","title":"Three good things"},{"kind":"benefits","items":["A clearer head at night","Spotting what drains you and what helps","Easier sleep"]},{"kind":"moves","items":[{"label":"Stress","dir":"down"},{"label":"Sleep","dir":"up"},{"label":"Mood","dir":"up"}]}],"sort":223},{"key":"flow_10","title":"10-minute morning flow","pillar":"exercise","kind":"movement","slot":"morning","dur":10,"descr":"Ten minutes: your morning flow, longer.","how":"1. Breathe, move, twist, shake it out\n2. Outside if you can\n3. Same time each morning","res":[{"kind":"article","slug":"the-power-of-walking","title":"The power of walking"},{"kind":"benefits","items":["Looser, warmer, more awake","A calmer start","Daylight on top, if outside"]},{"kind":"moves","items":[{"label":"Energy","dir":"up"},{"label":"Mood","dir":"up"},{"label":"Focus","dir":"up"}]}],"sort":224},{"key":"move_2h","title":"Move 10 minutes every 2 hours","pillar":"exercise","kind":"movement","slot":"midday","dur":10,"descr":"Every 2 hours, stand up and move for 10 minutes.","how":"1. A walk if you can\n2. Stairs, a stretch, a call on your feet\n3. Set a quiet reminder","res":[{"kind":"article","slug":"the-power-of-walking","title":"The power of walking"},{"kind":"article","slug":"sitting-less","title":"Sitting less"},{"kind":"benefits","items":["Less stiffness","Sharper focus after the break","More steps without trying"]},{"kind":"moves","items":[{"label":"Focus","dir":"up"},{"label":"Energy","dir":"up"}]}],"sort":225}]'::jsonb) as h(key text, title text, pillar text, kind text, slot text, dur int, descr text, how text, res jsonb, sort int)
on conflict (pillar,title) do update set description=excluded.description, how_md=excluded.how_md, default_slot=excluded.default_slot, duration_min=excluded.duration_min,
  card_kind=excluded.card_kind, resources=excluded.resources, member_can_add=true, active=true, published_at=coalesce(public.habit_bank.published_at, now()), updated_at=now();
select jsonb_object_agg(h.key, b.id) into v_map
  from jsonb_to_recordset('[{"key":"log_meal","title":"Log a meal","pillar":"nutrition"},{"key":"checkin","title":"Do your functional check-in","pillar":"mind"},{"key":"mindful","title":"Mindful eating: no phone, chew, breathe, a glass of water","pillar":"nutrition"},{"key":"walk_5","title":"A 5-minute walk after eating","pillar":"exercise"},{"key":"move_3","title":"3 minutes of movement","pillar":"exercise"},{"key":"snack_opt","title":"Optional: an exercise snack","pillar":"exercise"},{"key":"stretch","title":"2 minutes of gentle stretching before bed","pillar":"recovery"},{"key":"daylight","title":"Daylight first thing: head out of the window, and breathe","pillar":"mind"},{"key":"caffeine","title":"No caffeine after 16:00","pillar":"sleep"},{"key":"rule_321","title":"The 3-2-1 rule: 3 h no food, 2 h no intense exercise, 1 h no screens","pillar":"sleep"},{"key":"mini_breath","title":"Optional: a mini breath before sleep","pillar":"mind"},{"key":"breathing","title":"5 minutes of breathing, once a day","pillar":"mind"},{"key":"three_good","title":"Write down three good things about your day","pillar":"emotion"},{"key":"flow_5","title":"5-minute morning flow","pillar":"exercise"},{"key":"snack_daily","title":"One exercise snack a day","pillar":"exercise"},{"key":"protein","title":"Protein at every meal","pillar":"nutrition"},{"key":"carbs","title":"Complex carbs over refined","pillar":"nutrition"},{"key":"walk_meal","title":"A short walk after every meal","pillar":"exercise"},{"key":"moments","title":"2 to 3 movement moments a day","pillar":"exercise"},{"key":"book","title":"A book instead of a screen","pillar":"sleep"},{"key":"wind_down","title":"10 minutes to wind down: box breathing or NSDR","pillar":"sleep"},{"key":"breath_2","title":"A second moment to breathe","pillar":"mind"},{"key":"reach_out","title":"Reach out to someone you care about","pillar":"emotion"},{"key":"writing","title":"5 minutes of writing: three good things, and what''s on your mind","pillar":"emotion"},{"key":"flow_10","title":"10-minute morning flow","pillar":"exercise"},{"key":"move_2h","title":"Move 10 minutes every 2 hours","pillar":"exercise"}]'::jsonb) as h(key text, title text, pillar text)
  join public.habit_bank b on b.pillar=h.pillar and b.title=h.title;
if (select count(*) from jsonb_object_keys(v_map))<>26 then raise exception 'habit map incomplete: %', v_map; end if;
-- 2 track_day 1-14
update public.track_day t set read_slug=d.read_slug, updated_at=now(),
  actions=(select jsonb_agg((cat->k) || jsonb_build_object('key',k,'new',d.nw ? k,'face','standard','habit_bank_id',v_map->>k) order by o) from jsonb_array_elements_text(d.ks) with ordinality as e(k,o))
  from jsonb_to_recordset('[{"day":1,"read_slug":"introduction-to-functional-health","ks":["log_meal","checkin"],"nw":["log_meal","checkin"]},{"day":2,"read_slug":"mindful-eating","ks":["log_meal","mindful","walk_5","checkin"],"nw":["mindful","walk_5"]},{"day":3,"read_slug":"little-and-often","ks":["move_3","log_meal","mindful","walk_5","snack_opt","checkin","stretch"],"nw":["move_3","snack_opt","stretch"]},{"day":4,"read_slug":"light-sets-your-body-clock","ks":["move_3","daylight","mindful","walk_5","snack_opt","caffeine","stretch","rule_321","mini_breath"],"nw":["daylight","caffeine","rule_321","mini_breath"]},{"day":5,"read_slug":"breathe-the-time-you-give-yourself","ks":["move_3","daylight","mindful","walk_5","snack_opt","breathing","caffeine","stretch","rule_321","mini_breath","three_good"],"nw":["breathing","three_good"]},{"day":6,"read_slug":"simple-actions-repeated","ks":["move_3","daylight","mindful","walk_5","snack_opt","breathing","caffeine","stretch","rule_321","mini_breath","three_good"],"nw":[]},{"day":7,"read_slug":"your-day-on-one-page","ks":["daylight","flow_5","mindful","walk_5","breathing","snack_daily","caffeine","stretch","rule_321","mini_breath","three_good"],"nw":["flow_5","snack_daily"]},{"day":8,"read_slug":"protein-at-every-meal-and-why-it-matters","ks":["daylight","flow_5","mindful","breathing","snack_daily","protein","carbs","walk_meal","caffeine","stretch","rule_321","mini_breath","three_good"],"nw":["protein","carbs","walk_meal"]},{"day":9,"read_slug":"muscle-a-long-term-investment","ks":["daylight","flow_5","mindful","breathing","protein","carbs","walk_meal","caffeine","moments","stretch","rule_321","mini_breath","three_good"],"nw":["moments"]},{"day":10,"read_slug":"your-evening-routine","ks":["daylight","flow_5","mindful","breathing","protein","carbs","walk_meal","caffeine","moments","rule_321","three_good","book","wind_down"],"nw":["book","wind_down"]},{"day":11,"read_slug":"connection-is-health","ks":["daylight","flow_5","mindful","breathing","protein","carbs","walk_meal","caffeine","moments","breath_2","reach_out","rule_321","book","wind_down","writing"],"nw":["breath_2","reach_out","writing"]},{"day":12,"read_slug":"the-power-of-walking","ks":["daylight","flow_10","mindful","breathing","protein","carbs","walk_meal","caffeine","moments","breath_2","reach_out","move_2h","rule_321","book","wind_down","writing"],"nw":["flow_10","move_2h"]},{"day":13,"read_slug":"habits-that-last","ks":["daylight","flow_10","mindful","breathing","protein","carbs","walk_meal","caffeine","moments","breath_2","reach_out","move_2h","rule_321","book","wind_down","writing"],"nw":[]},{"day":14,"read_slug":"what-a-personal-programme-adds","ks":["daylight","flow_10","mindful","breathing","protein","carbs","walk_meal","caffeine","moments","breath_2","reach_out","move_2h","rule_321","book","wind_down","writing"],"nw":[]}]'::jsonb) as d(day int, read_slug text, ks jsonb, nw jsonb)
 where t.track_code='foundation_v1' and t.day=d.day;
get diagnostics n = row_count; if n<>14 then raise exception 'track_day rows updated: %', n; end if;
-- 3 member tags day:N on the 29 articles
insert into public.kb_tags(kind,slug,label) select 'member','day:'||g,'day:'||g from generate_series(1,14) g on conflict (kind,slug) do nothing;
insert into public.kb_node_tags(node_id,tag_id)
select k.id, g.id from jsonb_to_recordset('[{"slug":"introduction-to-functional-health","day":1},{"slug":"what-your-meal-photos-tell-us","day":1},{"slug":"your-functional-check-in-explained","day":1},{"slug":"mindful-eating","day":2},{"slug":"the-5-minute-walk-after-eating","day":2},{"slug":"exercise-snacks-foundation","day":3},{"slug":"little-and-often","day":3},{"slug":"caffeine-and-your-sleep","day":4},{"slug":"light-sets-your-body-clock","day":4},{"slug":"the-3-2-1-rule","day":4},{"slug":"breathe-the-time-you-give-yourself","day":5},{"slug":"three-good-things","day":5},{"slug":"simple-actions-repeated","day":6},{"slug":"the-power-of-compounding","day":6},{"slug":"the-power-of-habits","day":6},{"slug":"your-day-on-one-page","day":7},{"slug":"complex-or-refined-carbs-why-it-matters","day":8},{"slug":"protein-at-every-meal-and-why-it-matters","day":8},{"slug":"the-walk-after-every-meal","day":8},{"slug":"muscle-a-long-term-investment","day":9},{"slug":"the-benefits-of-exercise-snacks","day":9},{"slug":"nsdr-explained","day":10},{"slug":"your-evening-routine","day":10},{"slug":"connection-is-health","day":11},{"slug":"the-habit-of-writing","day":11},{"slug":"sitting-less","day":12},{"slug":"the-power-of-walking","day":12},{"slug":"habits-that-last","day":13},{"slug":"what-a-personal-programme-adds","day":14}]'::jsonb) as x(slug text, day int)
  join public.kb_nodes k on k.slug=x.slug and k.space='patient_resources'
  join public.kb_tags g on g.kind='member' and g.slug='day:'||x.day
on conflict do nothing;
-- 4 French free articles hidden from the patient app only
select id into v_app from public.delivery_channels where slug='patient_app';
update public.kb_node_channels c set enabled=false, updated_at=now()
 where c.channel_id=v_app and c.enabled and c.node_id in (select id from public.kb_nodes where space='public_resources' and slug = any (array['anatomie-bonne-nuit','anti-inflammatoire-quotidien','ballonnements-vraies-causes','bouger-fonctionnel','comprendre-la-perimenopause','comprendre-ton-intestin','comprendre-score-fonctionnel','cortisol-poids','ecrans-melatonine','fer-energie','hormones-tableau-ensemble','jeune-intermittent-pour-qui','l-energie-cellulaire','l-inflammation-expliquee','la-coherence-cardiaque','coup-de-pompe-15h','le-sommeil-pilier-sante','le-stress-et-ton-corps','lire-ses-analyses','macros-micros-la-base','magnesium-lequel-choisir','microbiote-humeur','reparer-son-intestin','respiration-3-minutes']));
get diagnostics v_hidden = row_count;
-- self-checks
if v_hidden<>24 then raise exception 'french hidden %', v_hidden; end if;
if (select count(*) from public.habit_bank where id in (select value::uuid from jsonb_each_text(v_map)) and active and published_at is not null and member_can_add)<>26 then raise exception 'habit_bank rows not all active/published/addable'; end if;
if (select count(*) from public.track_day where track_code='foundation_v1' and day between 1 and 14)<>14 then raise exception 'days'; end if;
if exists (select 1 from public.track_day t, jsonb_array_elements(t.actions) a where t.track_code='foundation_v1' and (a->>'habit_bank_id' is null or not exists (select 1 from public.habit_bank b where b.id=(a->>'habit_bank_id')::uuid and b.active))) then raise exception 'unresolved habit_bank_id'; end if;
if exists (select 1 from public.track_day t, jsonb_array_elements(t.actions) a, jsonb_array_elements_text(a->'reads') r where t.track_code='foundation_v1' and not exists (select 1 from public.kb_nodes k where k.slug=r and k.status='published' and k.published_at is not null)) then raise exception 'unpublished reads slug'; end if;
if exists (select 1 from public.track_day t where track_code='foundation_v1' and day between 1 and 14 and not exists (select 1 from public.kb_nodes k where k.slug=t.read_slug and k.status='published')) then raise exception 'read_slug not published'; end if;
select count(*) into v_chk from public.kb_node_tags nt join public.kb_tags g on g.id=nt.tag_id where g.kind='member' and g.slug ~ '^day:[0-9]+$';
if v_chk<>29 then raise exception 'day tag links %', v_chk; end if;
if (select count(*)||'/'||md5(string_agg(id::text,',' order by id)) from public.content_list(p_channel_slug=>'website', p_allowed_tiers=>array['public_free']::public.library_visibility[], p_limit=>500))<>'2/45a1d6c8b3c2a222ff23a436a467cbef' then raise exception 'website list changed'; end if;
if (select count(*) from public.content_list(p_channel_slug=>'patient_app', p_allowed_tiers=>array['public_free']::public.library_visibility[], p_limit=>500))<>30 then raise exception 'app list count %', (select count(*) from public.content_list(p_channel_slug=>'patient_app', p_allowed_tiers=>array['public_free']::public.library_visibility[], p_limit=>500)); end if;
if (select count(*) from public.content_list(p_channel_slug=>'patient_app', p_allowed_tiers=>array['public_free']::public.library_visibility[], p_space=>'patient_resources', p_limit=>500) c where exists (select 1 from unnest(c.tags) t where t ~ '^day:[0-9]+$'))<>29 then raise exception 'english articles not all reach the app with a day tag'; end if;

end $do$;
